# Sing, O Muse, of the Checkout Tests Most Thorough!

```typescript
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { Checkout } from './Checkout';
import { CartProvider } from './CartContext';
import { PaymentProvider } from './PaymentContext';

const mockItems = [
  { id: '1', name: 'Divine Lyre', price: 99.99 },
  { id: '2', name: 'Heroic Sandals', price: 49.99 }
];

const mockProcessPayment = vi.fn();

const renderCheckout = (cartItems = mockItems) => {
  return render(
    <CartProvider initialItems={cartItems}>
      <PaymentProvider processPayment={mockProcessPayment}>
        <Checkout onComplete={vi.fn()} onCancel={vi.fn()} />
      </PaymentProvider>
    </CartProvider>
  );
};

describe('Checkout Component', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-OLYMPUS-123' });
  });

  describe('Happy Path - The Hero\'s Journey Through Checkout', () => {
    it('completes full checkout flow from shipping to confirmation', async () => {
      const user = userEvent.setup();
      renderCheckout();

      // Act: Fill shipping
      await user.type(screen.getByLabelText(/street address/i), '123 Mount Olympus');
      await user.type(screen.getByLabelText(/city/i), 'Athens');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Act: Fill payment
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Zeus Thunderbolt');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Assert: Review step shows details
      expect(screen.getByText(/divine lyre/i)).toBeInTheDocument();
      expect(screen.getByText(/ending in 1111/i)).toBeInTheDocument();

      // Act: Place order
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Assert: Confirmation appears
      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
        expect(screen.getByText(/ORD-OLYMPUS-123/i)).toBeInTheDocument();
      });
    });
  });

  describe('Validation - The Gates of Form Entry', () => {
    it('displays error when ZIP code format is invalid', async () => {
      const user = userEvent.setup();
      renderCheckout();

      await user.type(screen.getByLabelText(/zip code/i), 'ABCDE');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/valid zip code required/i);
      expect(screen.getByLabelText(/zip code/i)).toHaveAttribute('aria-invalid', 'true');
    });
  });

  describe('Error States - When Fate Intervenes', () => {
    it('displays payment error and allows retry', async () => {
      mockProcessPayment.mockRejectedValueOnce(new Error('Card declined by the gods'));
      const user = userEvent.setup();
      // ... navigate to review step, then:

      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
      });
      expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
    });
  });

  describe('Edge Cases - The Empty Cart Abyss', () => {
    it('displays empty cart message when no items present', () => {
      renderCheckout([]);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
      expect(screen.getByRole('button', { name: /continue shopping/i })).toBeInTheDocument();
    });
  });
});
